import csv,io,subprocess,collections
csv.field_size_limit(10**9)
def tsv(p):
    t=subprocess.run(['git','show','origin/main:'+p],capture_output=True,text=True).stdout
    return list(csv.DictReader(io.StringIO('\n'.join(l for l in t.splitlines() if not l.startswith('#'))),delimiter='\t'))
ids={r['resultado_id'] for r in tsv('data/corrida0/usos.tsv') if r['consumidor'].startswith('marcador:CRUCE::GOB.gobierno_digital.encig2025.edad_x_escolaridad::')}
print('resultados.tsv publicado, origen_numerico de esos RESULT:',dict(collections.Counter(r['origen_numerico'] for r in tsv('data/corrida0/resultados.tsv') if r['resultado_id'] in ids)))
